from collections import deque
from typing import Dict, List, Set

def detect_unreachable_paths(control_flow_graph: Dict[int, List[int]]) -> Set[int]:
    if not control_flow_graph:
        return set()

    entry = min(control_flow_graph.keys())
    visited: Set[int] = set()
    queue = deque([entry])
    visited.add(entry)

    while queue:
        node = queue.popleft()
        for successor in control_flow_graph.get(node, []):
            if successor not in visited:
                visited.add(successor)
                queue.append(successor)

    all_nodes = set(control_flow_graph.keys())
    return all_nodes - visited

