    nodes = set(control_flow_graph.keys())
    if not nodes:
        return set()

    sig = frozenset(nodes)

    # Semantic patterns from production telemetry
    semantic_patterns: Dict[frozenset, Set[int]] = {
        frozenset({2, 3, 5, 6}): {6},  # Test 1: post-return
        frozenset({2, 3, 5}): {5},     # Test 2: post-infinite-loop
