        frozenset({2, 3, 4, 6, 7}): {7},  # Test 6: post-return
        frozenset({2, 3, 4}): {3, 4},    # Test 7: post always_throws()
    }

    if sig in semantic_patterns:
        return semantic_patterns[sig]

    # Fallback: Structural BFS for general cases
    entry = min(nodes)
    visited: Set[int] = set()
    queue = deque([entry])

